# Generated by coco shell init. Add the initialization command to your shell rc file.
coco() {
    @SETUP@
    local _coco_arg _coco_command _coco_destination _coco_scoped=0
    local -a _coco_prefix=()
    for _coco_arg in "$@"; do
        # `test` stays case-sensitive even when Bash's nocasematch is enabled.
        if [ "$_coco_arg" = cd ]; then
            shift "${#_coco_prefix[@]}"
            shift
            for _coco_arg in "$@"; do
                if [ "$_coco_arg" = -h ] || [ "$_coco_arg" = --help ]; then
                    command coco "${_coco_prefix[@]}" cd "$@"
                    return $?
                fi
            done
            _coco_destination=$(command coco "${_coco_prefix[@]}" path "$@") || return $?
            if [ -z "$_coco_destination" ]; then
                printf '%s\n' 'coco: no workspace path was returned' >&2
                return 1
            fi
            builtin cd -- "$_coco_destination"
            return $?
        fi
        for _coco_command in @COMMANDS@; do
            if [ "$_coco_arg" = "$_coco_command" ]; then
                break 2
            fi
        done
        if [ "$_coco_arg" = -a ] || [ "$_coco_arg" = --all-repos ] ||
            [ "$_coco_arg" = -g ] || [ "$_coco_arg" = --global ] ||
            [ "$_coco_arg" = --no-input ]; then
            :
        elif [ "${_coco_arg#-}" != "$_coco_arg" ] || [ "$_coco_scoped" -eq 1 ]; then
            break
        else
            _coco_scoped=1
        fi
        _coco_prefix+=("$_coco_arg")
    done
    command coco "$@"
}
